import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import test from 'node:test';

const script = new URL('isr-deploy.sh', import.meta.url);
const digest = `sha256:${'a'.repeat(64)}`;

function render(...args) {
  return execFileSync('bash', ['-s', '--', '--values', ...args], {
    encoding: 'utf8',
    input: readFileSync(script),
  });
}

test('renders a digest-pinned Helm values file', () => {
  const actual = render('ghcr.io/playgrifball/infinite-spartan-render:sha-1234567', digest, '0.1.5');
  assert.equal(actual, `# Generated by isr-deploy.sh. deploy/current keeps this file and the chart in one commit.
# infinite-spartan-render 0.1.5
image:
  repository: ghcr.io/playgrifball/infinite-spartan-render
  tag: "sha-1234567"
  digest: "${digest}"
`);
});

test('rejects an image without a tag', () => {
  assert.throws(() => render('ghcr.io/playgrifball/infinite-spartan-render', digest, '0.1.5'));
});

test('the release workflow deploys only after publishing, releasing', () => {
  const workflow = readFileSync(new URL('../workflows/helm-chart.yml', import.meta.url), 'utf8');
  assert.match(workflow, /\r?\n  deploy:\r?\n    needs: \[publish, release\]/);
  assert.match(workflow, /\.github\/scripts\/isr-deploy\.sh/);
  assert.match(workflow, /permissions:\r?\n      contents: write/);
});
